'use strict';
const fs=require('fs'),path=require('path');const{chromium}=require('playwright');
const BASE='https://plan-ex.ru/erpv2/',U=p=>new URL(p,BASE).href,OUT=path.resolve(process.env.P16_OUT||'P16_data_output'),SHOTS=path.join(OUT,'P16_screenshots');fs.mkdirSync(SHOTS,{recursive:true});
const COMPANY=27,OWNER='p14_owner_260804221827',PREFIX='UIUX_P16_';
function credentials(){const e=process.env.P16_CREDENTIALS_B64||'';return e?JSON.parse(Buffer.from(e,'base64').toString('utf8')):[]}function superadmin(){return credentials().find(x=>String(x?.role||'').toUpperCase()==='SUPERADMIN')}
async function login(b,u,pw){const c=await b.newContext({viewport:{width:1920,height:1080},deviceScaleFactor:1,locale:'ru-RU',timezoneId:'Europe/Moscow'}),p=await c.newPage();let ok=false;try{await p.goto(U('login'),{waitUntil:'domcontentloaded',timeout:45000});await p.locator('input[name="username"],input[name="email"],input[type="text"]').first().fill(u);await p.locator('input[type="password"]').fill(pw);await Promise.all([p.waitForLoadState('domcontentloaded').catch(()=>{}),p.locator('button[type="submit"],input[type="submit"]').first().click()]);await p.waitForTimeout(350);ok=!/\/login(?:[/?#]|$)/.test(p.url())}catch{}return{c,p,ok}}
function candidates(t,v){const a=[...v];for(const m of String(t).matchAll(/[A-Za-z0-9!@#$%^&*()_+\-=]{8,64}/g))a.push(m[0]);return[...new Set(a)].filter(x=>x!==OWNER&&!x.includes('@example.test')&&!/^[a-f0-9]{64}$/i.test(x))}
async function ownerSession(b){const s=superadmin(),x=await login(b,s.username,s.password);if(!x.ok)throw Error('superadmin login failed');await x.p.goto(U(`superadmin/companies/${COMPANY}/users`),{waitUntil:'domcontentloaded'});const f=x.p.locator(`form[action$="/superadmin/companies/${COMPANY}/owner/reset-password"]`).first(),n=x.p.waitForNavigation({waitUntil:'domcontentloaded'});await f.evaluate(z=>HTMLFormElement.prototype.submit.call(z));await n;const values=await x.p.locator('input,textarea,code,pre,[data-password]').evaluateAll(ns=>ns.map(y=>y.value||y.textContent||'').filter(Boolean)),list=candidates(await x.p.locator('body').innerText(),values);await x.c.close();for(const q of list){const y=await login(b,OWNER,q);if(y.ok){list.fill('');return y}await y.c.close()}throw Error('owner login failed')}
function inn10(seed){const nine=String(seed).replace(/\D/g,'').padStart(9,'0').slice(-9),d=[...nine].map(Number),k=[2,4,10,3,5,9,4,6,8].reduce((s,x,i)=>s+x*d[i],0)%11%10;return nine+k}
function png(label){return Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9Wl3pVQAAAAASUVORK5CYII=','base64')}
function pdf(label){return Buffer.from(`%PDF-1.4\n1 0 obj<</Type/Catalog/Pages 2 0 R>>endobj\n2 0 obj<</Type/Pages/Count 0>>endobj\n% ${label}\n%%EOF\n`,'utf8')}
async function fill(form,name,value){const x=form.locator(`[name="${name}"]`).first();if(!(await x.count()))return false;const tag=await x.evaluate(e=>e.tagName);if(tag==='SELECT'){await x.evaluate((e,v)=>{const o=[...e.options].find(z=>String(z.value)===String(v))||[...e.options].find(z=>z.value);if(o){e.value=o.value;e.dispatchEvent(new Event('input',{bubbles:true}));e.dispatchEvent(new Event('change',{bubbles:true}))}},String(value));}else await x.fill(String(value));return true}
async function submit(page,form,actionPart){const responses=[];const h=async z=>{if(z.url().includes(actionPart)){let body='';try{body=await z.text()}catch{}responses.push({status:z.status(),url:z.url(),body:body.slice(0,1200)})}};page.on('response',h);await form.evaluate(z=>z.requestSubmit());await page.waitForTimeout(650);page.off('response',h);return responses.at(-1)||null}
async function findId(page,pagePath,label,attr){await page.goto(U(pagePath),{waitUntil:'domcontentloaded'});const row=page.locator(`[${attr}]`).filter({hasText:label}).first();return await row.count()?Number(await row.getAttribute(attr)):null}
async function createClient(p,i){const label=`${PREFIX}CLIENT_${String(i).padStart(2,'0')} ${i===2?'ООО Очень длинное юридическое название для проверки переноса и ширины таблицы':'ООО Клиент тестовый'}`;let id=await findId(p,'company/clients',label,'data-client-id');if(id)return{id,label,created:false};await p.goto(U('company/clients'));await p.locator('#open-client-create-modal').click();const f=p.locator('#client-create-modal form[action$="/company/clients/create"]');await fill(f,'short_name',label);await fill(f,'full_name',`${label} полное наименование`);await fill(f,'inn',inn10(770000000+i));await fill(f,'legal_address',i===7?'г. Москва, очень длинный юридический адрес, улица Проверочная, дом 100, строение 25, помещение 300':'г. Москва, ул. Тестовая, д. '+i);await fill(f,'actual_address',i===8?'г. Санкт-Петербург, максимально длинный фактический адрес для проверки таблиц и форм, набережная Интерфейсная, дом 88':'г. Москва, склад '+i);await fill(f,'comment',i===9?'Длинный комментарий '.repeat(20):`P16 client ${i}`);if(await f.locator('[name="contact_name"]').count()){await fill(f,'contact_name',`Контакт ${i}`);await fill(f,'contact_phone',`+7900100${String(i).padStart(4,'0')}`);await fill(f,'contact_email',`p16.client${i}@example.test`)}if(i%3===0&&await f.locator('input[type="file"]').count())await f.locator('input[type="file"]').first().setInputFiles({name:`UIUX_P16_клиент_${i}.png`,mimeType:'image/png',buffer:png(label)});const response=await submit(p,f,'/company/clients/create');id=await findId(p,'company/clients',label,'data-client-id');if(!id)throw Error(`client create failed ${i} ${JSON.stringify(response)}`);return{id,label,created:true}}
async function createContractor(p,i){const label=`${PREFIX}CONTRACTOR_${String(i).padStart(2,'0')} ${i===6?'ООО Перевозчик с чрезвычайно длинным наименованием для проверки Full HD таблицы':'ООО Перевозчик'}`;let id=await findId(p,'company/contractors',label,'data-contractor-id');if(id)return{id,label,created:false};await p.goto(U('company/contractors'));await p.locator('#open-contractor-create-modal').click();const f=p.locator('#contractor-create-modal form[action$="/company/contractors/create"]');await fill(f,'short_name',label);await fill(f,'full_name',`${label} полное наименование`);await fill(f,'inn',inn10(780000000+i));await fill(f,'legal_address',`г. Казань, ул. Перевозчиков, д. ${i}`);await fill(f,'director_name',`Директор Тестовый ${i}`);await fill(f,'checking_account',`40702810${String(i).padStart(12,'0')}`);await fill(f,'bank_name','Тестовый банк, не реальные реквизиты');await fill(f,'comment',`UIUX_P16 contractor ${i}`);if(await f.locator('[name="contact_name"]').count()){await fill(f,'contact_name',`Диспетчер ${i}`);await fill(f,'contact_phone',`+7900200${String(i).padStart(4,'0')}`);await fill(f,'contact_email',`p16.contractor${i}@example.test`)}if(i%4===0&&await f.locator('input[type="file"]').count())await f.locator('input[type="file"]').first().setInputFiles({name:`UIUX_P16_перевозчик_${i}.png`,mimeType:'image/png',buffer:png(label)});const response=await submit(p,f,'/company/contractors/create');id=await findId(p,'company/contractors',label,'data-contractor-id');if(!id)throw Error(`contractor create failed ${i} ${JSON.stringify(response)}`);return{id,label,created:true}}
async function createDriver(p,i,contractorId){const label=`${PREFIX}DRIVER_${String(i).padStart(2,'0')} ${i===2?'Иванов-Александров Владимир Владимирович Длинное ФИО':'Водитель Тестовый'}`;let id=await findId(p,'company/drivers',label,'data-driver-id');if(id)return{id,label,created:false};await p.goto(U('company/drivers'));await p.locator('#open-driver-create-modal').click();const f=p.locator('#driver-create-modal form[action$="/company/drivers/create"]');await fill(f,'full_name',label);await fill(f,'contractor_id',contractorId);await fill(f,'phone',`+7900300${String(i).padStart(4,'0')}`);await fill(f,'birth_date',`198${i%10}-01-15`);await fill(f,'license_number',`P16-${100000+i}`);await fill(f,'comment',`UIUX_P16 driver ${i}`);if(i%3===0&&await f.locator('input[type="file"]').count())await f.locator('input[type="file"]').first().setInputFiles({name:`UIUX_P16_водитель_${i}.png`,mimeType:'image/png',buffer:png(label)});const response=await submit(p,f,'/company/drivers/create');id=await findId(p,'company/drivers',label,'data-driver-id');if(!id)throw Error(`driver create failed ${i} ${JSON.stringify(response)}`);return{id,label,created:true}}
async function createVehicle(p,i,contractorId){const plate=`А${String(160+i).padStart(3,'0')}АА77`,label=`${PREFIX}VEHICLE_${String(i).padStart(2,'0')}`;let id=await findId(p,'company/vehicle-sets',plate,'data-vehicle-set-id');if(id)return{id,label,plate,created:false};await p.goto(U('company/vehicle-sets'));await p.locator('#open-vehicle-set-create-modal').click();await p.locator('input[name="vehicle_set_type"][value="single"]').check();const f=p.locator('#vehicle-set-create-form');await fill(f,'contractor_id',contractorId);await fill(f,'single_vehicle[unit_type]',i%4===0?'trailer':'truck');await fill(f,'single_vehicle[make]',i===5?`${label} Марка и модель с очень длинным названием для проверки переноса`:label);await fill(f,'single_vehicle[registration_number]',plate);await fill(f,'single_vehicle[owner_full_name]',`Собственник ${i}`);await fill(f,'single_vehicle[diagnostic_card_number]',String(900000+i));if(i%3===0&&await f.locator('input[type="file"]').count())await f.locator('input[type="file"]').first().setInputFiles({name:`UIUX_P16_ТС_${i}.png`,mimeType:'image/png',buffer:png(label)});const button=p.locator('button[type="submit"][form="vehicle-set-create-form"]');const responsePromise=p.waitForResponse(z=>z.url().includes('/company/vehicle-sets/create'),{timeout:30000}).catch(()=>null);await button.click();await responsePromise;await p.waitForTimeout(500);id=await findId(p,'company/vehicle-sets',plate,'data-vehicle-set-id');if(!id)throw Error(`vehicle create failed ${i}`);return{id,label,plate,created:true}}
async function createExecutor(p,i,contractorId,driverId,vehicleSetId,driverLabel){await p.goto(U('company/route-executors'));let id=await findId(p,'company/route-executors',driverLabel,'data-route-executor-id');if(id)return{id,created:false};await p.locator('#open-route-executor-create-modal').click();const f=p.locator('#route-executor-create-form');await fill(f,'contractor_id',contractorId);await fill(f,'driver_id',driverId);await fill(f,'vehicle_set_id',vehicleSetId);await fill(f,'comment',`${PREFIX}EXECUTOR_${String(i).padStart(2,'0')}`);await submit(p,f,'/company/route-executors/create');id=await findId(p,'company/route-executors',driverLabel,'data-route-executor-id');if(!id)throw Error(`executor create failed ${i}`);return{id,created:true}}
async function createTrip(p,i,clientId,contractorId,executorId){const label=`${PREFIX}TRIP_${String(i).padStart(2,'0')} ${i===2?'Рейс с очень длинным названием и подробным описанием груза для проверки таблицы':'Репрезентативный рейс'}`;let id=await findId(p,'company/trips/linear',label,'data-linear-route-id');if(id)return{id,label,created:false};await p.goto(U('company/trips/linear?show_create=1'));const f=p.locator('#linear-trip-create-form');await fill(f,'route_type','linear');await fill(f,'planned_loading_date',`${String(10+i).padStart(2,'0')}.09.2026`);await fill(f,'planned_unloading_date',`${String(11+i).padStart(2,'0')}.09.2026`);await fill(f,'client_id',clientId);await fill(f,'carrier_contractor_id',contractorId);await fill(f,'route_executor_id',executorId);await fill(f,'cargo_type_name',label);await fill(f,'customer_payments[0][amount]',String(120000+i*5000));await fill(f,'customer_payments[0][payment_method]','cashless');await fill(f,'customer_payments[0][condition_type]',i%3===0?'prepayment':'specific_date');if(i%3!==0)await fill(f,'customer_payments[0][specific_due_date]',`${String(20+i).padStart(2,'0')}.09.2026`);await fill(f,'carrier_payments[0][amount]',String(80000+i*3500));await fill(f,'carrier_payments[0][payment_method]','cashless');await fill(f,'carrier_payments[0][condition_type]','after_end');await fill(f,'carrier_payments[0][days_count]',String((i%7)+1));await fill(f,'carrier_payments[0][days_kind]',i%2?'calendar':'working');await fill(f,'comments',i===10?'Длинный комментарий '.repeat(30):`UIUX_P16 trip ${i}`);if(i%4===0&&await f.locator('input[type="file"]').count())await f.locator('input[type="file"]').first().setInputFiles({name:`UIUX_P16_рейс_${i}.pdf`,mimeType:'application/pdf',buffer:pdf(label)});const response=await submit(p,f,'/company/trips/linear/create');id=await findId(p,'company/trips/linear',label,'data-linear-route-id');if(!id)throw Error(`trip create failed ${i} ${JSON.stringify(response)}`);return{id,label,created:true}}
async function createDDS(p,i){const label=`${PREFIX}DDS_${String(i).padStart(2,'0')}`;await p.goto(U('company/finance/settings/dds-categories'));if((await p.locator('body').innerText()).includes(label))return{label,created:false};await p.locator('button').filter({hasText:/Создать статью/i}).click();const f=p.locator('form[action$="/company/finance/settings/dds-categories/create"]');await fill(f,'code',label);await fill(f,'name',`${label} ${['Доход перевозка','Расход перевозчик','Топливо','Зарплата','Налоги','Кассовый перевод','Прочий доход','Прочий расход'][i-1]}`);await fill(f,'flow_type',i<3||i===7?'inflow':'outflow');await fill(f,'activity_type','operating');await fill(f,'sort_order',String(100+i));await submit(p,f,'/company/finance/settings/dds-categories/create');if(!(await p.locator('body').innerText()).includes(label))throw Error(`dds create failed ${i}`);return{label,created:true}}
async function createInvoice(p,i,clientId,contractorId){const label=`${PREFIX}INV_${String(i).padStart(2,'0')}`;await p.goto(U('company/finance/invoices'));if((await p.locator('body').innerText()).includes(label))return{label,created:false};await p.locator('button').filter({hasText:/Создать счёт/i}).click();const f=p.locator('form[action$="/company/finance/invoices/create"]');await fill(f,'invoice_type',i%2?'outgoing':'incoming');await fill(f,'counterparty_type',i%2?'client':'contractor');await fill(f,'counterparty_id',i%2?clientId:contractorId);await fill(f,'invoice_number',label);await fill(f,'invoice_date',`2026-09-${String((i%20)+1).padStart(2,'0')}`);await fill(f,'amount',String(10000+i*7500));await fill(f,'currency','RUB');await fill(f,'payment_status',i%4===0?'paid':i%3===0?'partial':'unpaid');await fill(f,'planned_payment_date',i===7?'2026-08-01':`2026-10-${String((i%20)+1).padStart(2,'0')}`);await fill(f,'comment',i===12?'Длинный комментарий к счёту '.repeat(20):`${label} synthetic`);const response=await submit(p,f,'/company/finance/invoices/create');await p.goto(U('company/finance/invoices'));if(!(await p.locator('body').innerText()).includes(label))throw Error(`invoice create failed ${i} ${JSON.stringify(response)}`);return{label,created:true}}
async function createMoneyAccount(p,i){const label=`${PREFIX}CASH_${String(i).padStart(2,'0')}`;await p.goto(U('company/finance/cash'));if((await p.locator('body').innerText()).includes(label))return{label,created:false};await p.locator('button').filter({hasText:/Создать кассу/i}).click();const forms=p.locator('form:visible');const f=forms.filter({has: p.locator('input,select,textarea')}).last();const names=await f.locator('input,select,textarea').evaluateAll(ns=>ns.map(n=>n.name).filter(Boolean));for(const name of names){if(name==='_csrf_token')continue;if(/name|title|label/i.test(name))await fill(f,name,label);else if(/currency/i.test(name))await fill(f,name,'RUB');else if(/balance|amount/i.test(name))await fill(f,name,String(i*100000));else if(/comment|description/i.test(name))await fill(f,name,`${label} synthetic cash`);else if(/type/i.test(name))await fill(f,name,'cash')}const invalid=await f.evaluate(z=>[...z.elements].filter(e=>typeof e.checkValidity==='function'&&!e.checkValidity()).map(e=>e.name));if(invalid.length)return{label,created:false,blocked:`required:${invalid.join(',')}`,fields:names};await f.evaluate(z=>z.requestSubmit());await p.waitForTimeout(600);await p.goto(U('company/finance/cash'));return{label,created:(await p.locator('body').innerText()).includes(label),fields:names}}
async function createCashOperation(p,i){const label=`${PREFIX}CASH_OP_${String(i).padStart(2,'0')}`;await p.goto(U('company/finance/cash'));if((await p.locator('body').innerText()).includes(label))return{label,created:false};const account=await p.locator('select[name="money_account_id"] option').evaluateAll(os=>os.map(o=>o.value).filter(Boolean)).catch(()=>[]);if(!account.length)return{label,created:false,blocked:'NO_MONEY_ACCOUNT'};await p.locator('button').filter({hasText:/Приход\/Расход/i}).click();const f=p.locator('form[action$="/company/finance/cash/operation-create"]');await fill(f,'operation_type',i<=5?'income':'expense');await fill(f,'money_account_id',account[(i-1)%account.length]);await fill(f,'amount',String(5000+i*1000));await fill(f,'operation_date',`2026-09-${String((i%20)+1).padStart(2,'0')}`);await fill(f,'purpose',label);await fill(f,'comment',`${label} synthetic operation`);await f.evaluate(z=>z.requestSubmit());await p.waitForTimeout(500);await p.goto(U('company/finance/cash'));return{label,created:(await p.locator('body').innerText()).includes(label)}}
(async()=>{const result={status:'FAIL',tenantId:COMPANY,created:{clients:[],contractors:[],drivers:[],vehicles:[],executors:[],trips:[],dds:[],moneyAccounts:[],cashOperations:[],invoices:[]},counts:{},consoleErrors:[],pageErrors:[],requestFailures:[],httpFailures:[],errors:[]};let b,o;try{b=await chromium.launch({headless:true});o=await ownerSession(b);const p=o.p;p.on('console',m=>{if(m.type()==='error')result.consoleErrors.push(m.text())});p.on('pageerror',e=>result.pageErrors.push(String(e.message||e)));p.on('requestfailed',q=>result.requestFailures.push(q.url()));p.on('response',z=>{if(z.status()>=500)result.httpFailures.push({status:z.status(),url:z.url()})});const clients=[],contractors=[],drivers=[],vehicles=[];for(let i=1;i<=12;i++){const x=await createClient(p,i);clients.push(x);result.created.clients.push(x)}for(let i=1;i<=12;i++){const x=await createContractor(p,i);contractors.push(x);result.created.contractors.push(x)}for(let i=1;i<=12;i++){const x=await createDriver(p,i,contractors[(i-1)%12].id);drivers.push(x);result.created.drivers.push(x)}for(let i=1;i<=12;i++){const x=await createVehicle(p,i,contractors[(i-1)%12].id);vehicles.push(x);result.created.vehicles.push(x)}const executors=[];for(let i=1;i<=4;i++){const x=await createExecutor(p,i,contractors[i-1].id,drivers[i-1].id,vehicles[i-1].id,drivers[i-1].label);executors.push(x);result.created.executors.push(x)}for(let i=1;i<=15;i++)result.created.trips.push(await createTrip(p,i,clients[(i-1)%12].id,contractors[(i-1)%12].id,executors[(i-1)%4].id));for(let i=1;i<=8;i++)result.created.dds.push(await createDDS(p,i));for(let i=1;i<=2;i++)result.created.moneyAccounts.push(await createMoneyAccount(p,i));for(let i=1;i<=10;i++)result.created.cashOperations.push(await createCashOperation(p,i));for(let i=1;i<=12;i++)result.created.invoices.push(await createInvoice(p,i,clients[(i-1)%12].id,contractors[(i-1)%12].id));for(const [key,items] of Object.entries(result.created))result.counts[key]={total:items.length,created:items.filter(x=>x.created).length,reused:items.filter(x=>x.created===false&&!x.blocked).length,blocked:items.filter(x=>x.blocked).length};for(const [idx,url] of ['company/clients','company/contractors','company/drivers','company/vehicle-sets','company/trips/linear','company/finance/cash','company/finance/invoices'].entries()){await p.goto(U(url),{waitUntil:'networkidle'});await p.screenshot({path:path.join(SHOTS,`P16_${String(idx+1).padStart(3,'0')}_OWNER_${url.replaceAll('/','_')}_populated_1920x1080.png`),fullPage:false})}result.status=result.created.clients.length===12&&result.created.contractors.length===12&&result.created.drivers.length===12&&result.created.vehicles.length===12&&result.created.trips.length===15&&result.created.dds.length===8&&result.created.invoices.length===12&&result.pageErrors.length===0&&result.requestFailures.length===0&&result.httpFailures.length===0?'PASS':'FAIL'}catch(e){result.errors.push({name:e.name||'Error',message:String(e.message||e).slice(0,1200)})}finally{if(o?.c)await o.c.close().catch(()=>{});if(b)await b.close().catch(()=>{});fs.writeFileSync(path.join(OUT,'P16_02_TEST_DATA_CREATED.json'),JSON.stringify(result,null,2));console.log('P16_BULK_DATA='+result.status);process.exitCode=result.status==='PASS'?0:1}})();
